package com.example.authservice.service;

import com.example.authservice.entity.Token;
import com.example.authservice.repository.TokenRepository;
import com.example.authservice.util.TokenUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.Instant;
import java.util.List;
import java.util.stream.Collectors;

@Service
public class TokenService {
    @Autowired
    private TokenRepository tokenRepository;

    @Transactional
    public void issueTokens(String userId, String username) {
        // Issue Access Token (10 minutes)
        String accessToken = TokenUtils.generateToken();
        Instant now = Instant.now();
        Token access = new Token();
        access.setTokenValue(accessToken);
        access.setUserId(userId);
        access.setTokenType("ACCESS");
        access.setIssuedAt(now);
        access.setExpiresAt(now.plusSeconds(600)); // 10 minutes
        access.setIsRevoked(false);
        access.setIsConsumed(false);
        tokenRepository.save(access);

        // Issue Refresh Token (24 hours)
        String refreshToken = TokenUtils.generateToken();
        Token refresh = new Token();
        refresh.setTokenValue(refreshToken);
        refresh.setUserId(userId);
        refresh.setTokenType("REFRESH");
        refresh.setIssuedAt(now);
        refresh.setExpiresAt(now.plusSeconds(86400)); // 24 hours
        refresh.setIsRevoked(false);
        refresh.setIsConsumed(false);
        tokenRepository.save(refresh);

        // Issue One-Time Token (5 minutes)
        String oneTimeToken = TokenUtils.generateToken();
        Token oneTime = new Token();
        oneTime.setTokenValue(oneTimeToken);
        oneTime.setUserId(userId);
        oneTime.setTokenType("ONE_TIME");
        oneTime.setIssuedAt(now);
        oneTime.setExpiresAt(now.plusSeconds(300)); // 5 minutes
        oneTime.setIsRevoked(false);
        oneTime.setIsConsumed(false);
        tokenRepository.save(oneTime);
    }

    @Transactional(readOnly = true)
    public Token findTokenByValue(String tokenValue, String userId) {
        return tokenRepository.findByTokenValueAndUserIdAndIsRevokedFalseAndIsConsumedFalse(tokenValue, userId)
                .orElse(null);
    }

    @Transactional
    public boolean consumeOneTimeToken(String tokenValue, String userId) {
        Token token = tokenRepository.findByTokenValueAndUserIdAndIsRevokedFalseAndIsConsumedFalse(tokenValue, userId)
                .orElse(null);
        if (token == null) return false;
        if (token.getExpiresAt().isBefore(Instant.now())) return false;
        token.setIsConsumed(true);
        tokenRepository.save(token);
        return true;
    }

    @Transactional
    public boolean revokeToken(String tokenValue, String userId) {
        Token token = tokenRepository.findByTokenValueAndUserIdAndIsRevokedFalseAndIsConsumedFalse(tokenValue, userId)
                .orElse(null);
        if (token != null) {
            token.setIsRevoked(true);
            tokenRepository.save(token);
            return true;
        }
        return false;
    }

    @Transactional
    public boolean isTokenValid(String tokenValue, String userId, String tokenType) {
        Token token = tokenRepository.findByTokenValueAndUserIdAndIsRevokedFalseAndIsConsumedFalse(tokenValue, userId)
                .orElse(null);
        if (token == null) return false;
        if (token.getTokenType().equals(tokenType)) {
            return !token.getExpiresAt().isBefore(Instant.now());
        }
        return false;
    }

    @Transactional
    public boolean isTokenValidForRenewal(String tokenValue, String userId) {
        Token token = tokenRepository.findByTokenValueAndUserIdAndIsRevokedFalseAndIsConsumedFalse(tokenValue, userId)
                .orElse(null);
        if (token == null) return false;
        if (token.getTokenType().equals("REFRESH")) {
            return !token.getExpiresAt().isBefore(Instant.now());
        }
        return false;
    }

    @Transactional
    public void logoutUser(String userId) {
        List<Token> tokens = tokenRepository.findByUserIdAndIsRevokedFalseAndIsConsumedFalse(userId);
        for (Token token : tokens) {
            token.setIsRevoked(true);
            tokenRepository.save(token);
        }
    }

    @Transactional
    public void cleanup() {
        long deleted = tokenRepository.deleteByIsRevokedTrueOrIsConsumedTrueOrExpiresAtBefore(Instant.now());
        System.out.println("[CLEANUP] Deleted " + deleted + " tokens");
    }

    @Transactional
    public boolean isUserLoggedIn(String userId) {
        List<Token> tokens = tokenRepository.findByUserIdAndIsRevokedFalseAndIsConsumedFalse(userId);
        return !tokens.isEmpty();
    }
}
EOF"}

